static shape_fn shape_find(const shape_entry*entries,size_t count,const char*name){if(!name)return NULL;size_t lo=0,hi=count;while(lo<hi){size_t mid=lo+(hi-lo)/2;int order=strcmp(name,entries[mid].name);if(!order)return entries[mid].check;if(order<0)hi=mid;else lo=mid+1;}return NULL;}
static bool depth_ok(const node*x,unsigned depth){if(!shape_tick()||!x||depth>64)return false;for(size_t i=0;i<x->count;i++)if(!depth_ok(x->items[i],depth+1))return false;return true;}
bool wm_shape_c_type(const char*name,const node*x){shape_fn check=shape_find(c_types,sizeof(c_types)/sizeof(*c_types),name);return check&&depth_ok(x,0)&&check(x,0);}
bool wm_shape_model(const char*name,const node*x){shape_fn check=shape_find(model_types,sizeof(model_types)/sizeof(*model_types),name);return check&&depth_ok(x,0)&&check(x,0);}
